def apply_decisions(rows, texts):
    for r in rows:
        i=r['index']; t=texts.get(str(i),''); lines=t.splitlines()
        r['scope_clarification']='治理/财务/合规业务内容可分析；2026-11-12用户澄清后复核'
        r['unresolved_parts']=[]
        if i in DECISIONS and r.get('stat_stable'):
            ranges,themes,knowledge,limits=DECISIONS[i]
            r.update(status='已分析',reason='已实际阅读所列业务片段并完成语义核定；历史意见/内部规则，不代表现行事实批准',themes=themes,knowledge=knowledge,analysis_completed=True,analysis_scope='所列业务片段；未审阅部分不宣称全文核验',unresolved_parts=[limits])
        elif i in PENDING and r.get('stat_stable'):
            ranges,reason,note=PENDING[i]
            r.update(status='待核',reason=reason,analysis_completed=False,analysis_scope='最小内容辨识与隔离',safe_observation=note,unresolved_parts=[reason])
        else:
            if r['status']=='已分析': r['analysis_scope']='全文阅读，业务设计分析；现行事实与专业意见不核验'
            continue
        prefix='T' if r['path'].endswith('.html') else 'L'
        r['locators']=[f'{prefix}{a}-{prefix}{min(b,len(lines))}' for a,b in ranges]
        selected={j for a,b in ranges for j in range(a,min(b,len(lines))+1)}
        r['model_review_chars']=len('\n'.join(lines[j-1] for j in sorted(selected)))
        r['model_review_lines']=r['locators']
        r['reviewed_line_count']=len(selected)
        r['source_line_count']=len(lines)
        r['unreviewed_line_count']=len(lines)-len(selected)
    return rows
